fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // Create a vector of tuples containing the indices and their corresponding values
    let mut indices_values = vec![(i, valores[i]), (j, valores[j]), (k, valores[k])];
    
    // Sort the vector by values in descending order
    indices_values.sort_by(|a, b| b.1.cmp(&a.1));
    
    // The first two indices in the sorted vector are the ones we want to return
    let (first_index, _) = indices_values[0];
    let (second_index, _) = indices_values[1];
    
    (first_index, second_index)
}